import{gt as e,nt as t,o as n,rt as r}from"./chunks/framework.CTZrU_RR.js";var i=JSON.parse(`{"title":"Module Options Reference","description":"Every option the module accepts, with its type, default and purpose — read at build time from the type definition.","frontmatter":{"title":"Module Options Reference","description":"Every option the module accepts, with its type, default and purpose — read at build time from the type definition.","outline":[2,3]},"headers":[],"relativePath":"api/module-options.md","filePath":"api/module-options.md","lastUpdated":1785931233000}`),a={name:`api/module-options.md`};function o(n,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[r(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /nuxt-i18n-micro/api/module-options.md for this page in Markdown format</div><h1 id="module-options-reference" tabindex="-1">Module Options Reference <a class="header-anchor" href="#module-options-reference" aria-label="Permalink to “Module Options Reference”">​</a></h1><p>Every option <code>nuxt-i18n-micro</code> accepts, read at build time from the <code>ModuleOptions</code> interface in <a href="https://github.com/s00d/nuxt-i18n-micro/blob/main/packages/types/src/index.ts" target="_blank" rel="noreferrer"><code>packages/types/src/index.ts</code></a>. Nothing here is written by hand, so it cannot fall behind the code — types, defaults and descriptions come from the declaration itself.</p><p>For what these options <em>mean</em> together — which combinations make sense, what changes when you switch strategy, worked examples — read <a href="/nuxt-i18n-micro/guide/configuration">Configuration</a>. This page is the exhaustive list; that one is the explanation.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> defineNuxtConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  modules: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;nuxt-i18n-micro&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  i18n: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    locales: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      { code: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;en&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, iso: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;en-US&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dir: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ltr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      { code: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;de&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, iso: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;de-DE&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dir: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ltr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    defaultLocale: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;en&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>Nested options appear under their dotted path, so <code>translationPayloads.mode</code> is the <code>mode</code> key inside the <code>translationPayloads</code> object.</p><h2 id="locales-and-routing" tabindex="-1">Locales and routing <a class="header-anchor" href="#locales-and-routing" aria-label="Permalink to “Locales and routing”">​</a></h2><p>Which languages exist and how they appear in the URL.</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>locales</code></td><td><code>Locale[]</code></td><td><code>[]</code></td><td>List of supported locales. Each entry defines a locale code plus optional metadata (ISO, direction, display name, etc.).</td></tr><tr><td><code>strategy</code></td><td><code>Strategies</code></td><td><code>&#39;prefix_except_default&#39;</code></td><td>URL routing strategy for locale prefixes. - <code>&#39;no_prefix&#39;</code> — no locale in URL; locale stored in cookie. - <code>&#39;prefix_except_default&#39;</code> — prefix all locales except the default. - <code>&#39;prefix&#39;</code> — always prefix, including the default locale. - <code>&#39;prefix_and_default&#39;</code> — like <code>prefix</code>, but the default locale is also accessible without prefix.</td></tr><tr><td><code>defaultLocale</code></td><td><code>string</code></td><td><code>&#39;en&#39;</code></td><td>The locale to use when no locale can be determined from URL or user preferences. Also used as the fallback locale for missing translations when <code>fallbackLocale</code> is not set.</td></tr><tr><td><code>localeCookie</code></td><td><code>string | null</code></td><td><code>null</code></td><td>Cookie name for persisting the user&#39;s locale preference across sessions. Set to <code>null</code> to disable cookie-based persistence. Automatically set to <code>&#39;user-locale&#39;</code> for the <code>no_prefix</code> strategy if not provided.</td></tr><tr><td><code>globalLocaleRoutes</code></td><td><code>GlobalLocaleRoutes</code></td><td><code>{}</code></td><td>Global route-level locale configuration. Allows restricting or customizing locale routes for specific pages without modifying their components. - <code>false</code> — exclude the route from localization. - <code>Record&lt;LocaleCode, string&gt;</code> — custom per-locale paths.</td></tr><tr><td><code>customRegexMatcher</code></td><td><code>string | RegExp</code></td><td><code>undefined (uses built-in pattern based on locale codes)</code></td><td>Custom regular expression (or its string source) for matching locale codes in URL segments. All locale codes defined in <code>locales</code> must match this pattern, or a warning is emitted.</td></tr><tr><td><code>noPrefixRedirect</code></td><td><code>boolean</code></td><td><code>false</code></td><td>For <code>no_prefix</code> strategy: enable redirect from a locale-prefixed URL (e.g. <code>/en/about</code>) to the unprefixed version (<code>/about</code>).</td></tr><tr><td><code>excludePatterns</code></td><td><code>(string | RegExp)[]</code></td><td><code>undefined</code></td><td>URL patterns (strings or RegExp) to exclude from i18n processing entirely. Matching routes won&#39;t get locale prefixes, redirects, or translation loading. Internal Nuxt paths (<code>/__nuxt_error</code>, etc.) are always excluded automatically.</td></tr><tr><td><code>routeLocales</code></td><td><code>Record&lt;string, string[]&gt;</code></td><td>—</td><td>Per-route locale restrictions, extracted from <code>defineI18nRoute()</code> calls. Maps a route path (e.g. <code>&#39;/about&#39;</code>) to an array of allowed locale codes. Routes not listed have no restrictions (all locales allowed).</td></tr></tbody></table><h2 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to “Translations”">​</a></h2><p>Where translation files live and how keys are resolved.</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>translationDir</code></td><td><code>string</code></td><td><code>&#39;locales&#39;</code></td><td>Path to the directory containing translation JSON files, relative to the project root.</td></tr><tr><td><code>disableWatcher</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Disable the file watcher that auto-creates missing translation files in development mode.</td></tr><tr><td><code>routesLocaleLinks</code></td><td><code>{ [key: string]: string }</code></td><td><code>{}</code></td><td>Map route names to other route names to share the same translation files. For example, <code>{ &#39;about-us&#39;: &#39;about&#39; }</code> means the <code>about-us</code> page will use translations from the <code>about</code> page instead of its own.</td></tr><tr><td><code>plural</code></td><td><code>PluralFunc</code></td><td><code>built-in pluralization (form index by count)</code></td><td>Custom pluralization function. Receives <code>(key, count, params, locale, getter)</code> and should return the selected plural form as a string, or <code>null</code>/<code>undefined</code> to fall back to the built-in <code>defaultPlural</code> logic (so you can override only some locales). For the Nuxt module the function is serialized with <code>.toString()</code> into <code>.nuxt/i18n.plural.mjs</code> — it must be self-contained (no imports / outer scope). A file path string is <strong>not</strong> supported.</td></tr><tr><td><code>disablePageLocales</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Disable per-page translation files. When <code>true</code>, only global translations (<code>{locale}.json</code>) are loaded; page-specific files (<code>pages/{page}/{locale}.json</code>) are not generated or loaded.</td></tr><tr><td><code>fallbackLocale</code></td><td><code>string</code></td><td><code>undefined (no fallback; returns the raw key)</code></td><td>Global fallback locale code. When a translation key is missing in the active locale, the module looks it up in this locale before returning the key itself.</td></tr></tbody></table><h2 id="payloads-and-caching" tabindex="-1">Payloads and caching <a class="header-anchor" href="#payloads-and-caching" aria-label="Permalink to “Payloads and caching”">​</a></h2><p>How translations reach the browser. <a href="/nuxt-i18n-micro/guide/performance">Performance</a> explains what these change at runtime.</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>serverTranslationPreload</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Preload index-page translations in Nitro global middleware (server-only, private config).</td></tr><tr><td><code>apiBaseUrl</code></td><td><code>string</code></td><td><code>&#39;_locales&#39;</code></td><td>Base URL path segment for the translations API route (used in SSR/SSG data fetching). Can also be set via <code>NUXT_I18N_APP_BASE_URL</code> environment variable.</td></tr><tr><td><code>apiBaseClientHost</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Override the host used for client-side translation fetch requests. Useful when the client reaches the server via a different hostname than the one Nuxt sees. Can also be set via <code>NUXT_I18N_APP_BASE_CLIENT_HOST</code> environment variable.</td></tr><tr><td><code>apiBaseServerHost</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Override the host used for server-side translation fetch requests. Useful in container/microservice setups where the server reaches itself via an internal hostname. Can also be set via <code>NUXT_I18N_APP_BASE_SERVER_HOST</code> environment variable.</td></tr><tr><td><code>translationPayloads</code></td><td><code>TranslationPayloadOptions</code></td><td>—</td><td>Controls how translation payloads are emitted (Node: <code>public/&lt;apiBaseUrl&gt;</code>; Edge: Nitro <code>serverAssets</code>). - <strong>Node</strong>: <code>serverAssets</code> means local SSR via <code>readFile</code> under <code>public/</code> (no Rollup <code>raw:</code>). - <strong>Edge</strong>: <code>serverAssets</code> registers Nitro <code>serverAssets</code> (<code>assets:i18n</code>); it does not force a public copy. Keep the defaults for the usual all-in-one setup. For large Edge catalogs prefer <code>mode: &#39;source&#39;</code>. For CDN-backed deployments, disable local outputs and set <code>apiBaseClientHost</code> / <code>apiBaseServerHost</code>.</td></tr><tr><td><code>translationPayloads.mode</code></td><td><code>&#39;premerged&#39; | &#39;source&#39;</code></td><td><code>&#39;premerged&#39;</code></td><td>Translation payload strategy. - <code>premerged</code>: build-time <code>{page}/{locale}/data.json</code> matrix (default) - <code>source</code>: compact source files merged at runtime (prefer on Edge / large catalogs)</td></tr><tr><td><code>translationPayloads.serverAssets</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Local SSR payloads: Node reads <code>public/&lt;apiBaseUrl&gt;</code> (forces public copy); Edge embeds via Nitro <code>serverAssets</code>. - <strong>Node</strong>: no Nitro <code>serverAssets</code> (avoids Rollup <code>raw:</code>). SSR reads <code>public/&lt;apiBaseUrl|publicDir&gt;</code> as <code>{page}/{locale}/data.json</code>; when this is <code>true</code>, a public copy is forced even if <code>publicAssets</code> is false. - <strong>Edge</strong> (<code>nitro.node === false</code>): Nitro <code>serverAssets</code> (<code>assets:i18n</code>) with the same layout as <code>mode</code>. Does <strong>not</strong> force a public copy — set <code>publicAssets: true</code> for CDN.</td></tr><tr><td><code>translationPayloads.serverHandler</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Register the built-in server route at <code>/{apiBaseUrl}/:page/:locale/data.json</code>. Disable this when translation payloads are served from an external host/CDN.</td></tr><tr><td><code>translationPayloads.publicAssets</code></td><td><code>boolean</code></td><td><code>true in premerged mode, false in source mode</code></td><td>Copy payloads into Nitro public output. Premerged → <code>{page}/{locale}/data.json</code> under <code>apiBaseUrl</code>; source → compact tree. On Node this tree is also the SSR source when <code>serverAssets</code> forces a public copy.</td></tr><tr><td><code>translationPayloads.prerenderRoutes</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Opt in to Nitro-prerender <code>/{apiBaseUrl}/.../data.json</code>. Usually redundant when premerged <code>publicAssets</code> already wrote those files.</td></tr><tr><td><code>translationPayloads.publicDir</code></td><td><code>string</code></td><td>—</td><td>Public output folder relative to Nitro public root. Defaults to <code>apiBaseUrl</code> (<code>_locales</code>). So static files match client fetch URLs (<code>/{apiBaseUrl}/{page}/{locale}/data.json</code>).</td></tr><tr><td><code>translationPayloads.warnFileCount</code></td><td><code>number</code></td><td><code>500</code></td><td>Warn during build when generated payload file count exceeds this threshold.</td></tr><tr><td><code>translationPayloads.warnSizeBytes</code></td><td><code>number</code></td><td><code>10485760 (10 MB)</code></td><td>Warn during build when generated payload total size exceeds this threshold in bytes.</td></tr></tbody></table><h2 id="seo" tabindex="-1">SEO <a class="header-anchor" href="#seo" aria-label="Permalink to “SEO”">​</a></h2><p>Meta tags generated for each localized page.</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>meta</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Generate SEO meta tags (<code>hreflang</code>, <code>canonical</code>, <code>og:url</code>, <code>og:locale</code>) automatically.</td></tr><tr><td><code>metaBaseUrl</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Base URL for SEO meta tags (canonical, og:url, hreflang). - A concrete URL string (e.g. <code>&#39;https://example.com&#39;</code>) — used as-is (highest priority). - <code>undefined</code> — falls back to <code>site.url</code> from <code>nuxt-site-config</code> when that module is present, otherwise the current request origin (<code>useRequestURL().origin</code> on server, <code>window.location.origin</code> on client).</td></tr><tr><td><code>metaTrustForwardedHost</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Trust the <code>X-Forwarded-Host</code> header when resolving the base URL for meta tags. Enable when the app runs behind a reverse proxy (nginx, Cloudflare, AWS ALB, etc.) that sets this header to the real client-facing hostname.</td></tr><tr><td><code>metaTrustForwardedProto</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Trust the <code>X-Forwarded-Proto</code> header when resolving the protocol for meta tags. Enable when the app runs behind a TLS-terminating proxy so that canonical URLs use <code>https://</code> even though the app itself listens on HTTP.</td></tr><tr><td><code>canonicalQueryWhitelist</code></td><td><code>string[]</code></td><td><code>[&#39;page&#39;, &#39;sort&#39;, &#39;filter&#39;, &#39;search&#39;, &#39;q&#39;, &#39;query&#39;, &#39;tag&#39;]</code></td><td>List of query parameter names preserved in canonical and <code>og:url</code> meta tags. Parameters not in this list are stripped from the canonical URL.</td></tr></tbody></table><h2 id="detection-and-redirects" tabindex="-1">Detection and redirects <a class="header-anchor" href="#detection-and-redirects" aria-label="Permalink to “Detection and redirects”">​</a></h2><p>Choosing a locale for a visitor who has not picked one.</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>redirects</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Enable automatic locale-based redirects. When <code>true</code>, visitors are redirected to their preferred locale (detected from cookie, <code>Accept-Language</code> header, or the default) on the first visit.</td></tr><tr><td><code>autoDetectLanguage</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Automatically detect the user&#39;s preferred language from the <code>Accept-Language</code> HTTP header. Used in combination with <code>autoDetectPath</code> to decide when detection occurs.</td></tr><tr><td><code>autoDetectPath</code></td><td><code>string</code></td><td><code>&#39;/&#39;</code></td><td>Where cookie / Accept-Language preference redirects may run (when <code>redirects</code> is enabled). - <code>&#39;/&#39;</code> — only <code>/</code> (deep links in the default locale stay reachable; default) - <code>&#39;no_prefix&#39;</code> — only paths without a locale prefix - <code>&#39;*&#39;</code> — every path, including rewriting an explicit locale prefix (e.g. <code>/fr/about</code> → <code>/de/about</code> when the cookie prefers <code>de</code>) - any other string — exact path match (e.g. <code>&#39;/welcome&#39;</code>) Prefixed strategy cleanup (e.g. <code>/en</code> → <code>/</code> under <code>prefix_except_default</code>) is not gated.</td></tr></tbody></table><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to “Registration”">​</a></h2><p>Parts of the module you can switch off.</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>define</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Register the <code>defineI18nRoute()</code> macro plugin, enabling per-page <code>defineI18nRoute()</code> calls.</td></tr><tr><td><code>plugin</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Register the core i18n plugin that provides <code>$t()</code>, <code>$tc()</code>, <code>$getLocale()</code>, <code>$switchLocale()</code>, and other runtime helpers.</td></tr><tr><td><code>hooks</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Register the i18n hooks plugin that provides <code>i18n:register</code> and <code>i18n:beforeLocaleSwitch</code> / <code>i18n:afterLocaleSwitch</code> app-level hooks.</td></tr><tr><td><code>components</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Register built-in i18n components (<code>&lt;i18n-link&gt;</code>, <code>&lt;i18n-switcher&gt;</code>, <code>&lt;i18n-t&gt;</code>, <code>&lt;i18n-group&gt;</code>). Set to <code>false</code> to disable automatic component registration (e.g. if you don&#39;t use them and want to reduce the module footprint).</td></tr><tr><td><code>types</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Generate TypeScript type declarations for <code>useI18n</code>, <code>$t</code>, and related helpers based on the translation keys in your default locale files.</td></tr><tr><td><code>debug</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Enable verbose debug logging for locale detection, route generation, and translation loading.</td></tr></tbody></table><h2 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to “Other”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>hreflangBaseLanguage</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Also emit a bare-language <code>hreflang</code> derived from each locale&#39;s <code>iso</code> (e.g. <code>es-ES</code> → also <code>es</code>). The first regional locale in <code>locales</code> claims the bare tag for that language. Routing <code>code</code> is never used — only <code>iso || code</code>.</td></tr><tr><td><code>vueDevtools</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Register Vue DevTools inspector and timeline in dev (browser extension). Separate from the Nuxt DevTools custom tab.</td></tr><tr><td><code>localizedRouteNamePrefix</code></td><td><code>string</code></td><td><code>&#39;localized-&#39;</code></td><td>Prefix prepended to localized route names (e.g. <code>&#39;localized-index&#39;</code>). Used internally to distinguish original routes from generated locale variants.</td></tr><tr><td><code>routeDisableMeta</code></td><td><code>Record&lt;string, boolean | string[]&gt;</code></td><td>—</td><td>Per-route meta tag disabling, extracted from <code>defineI18nRoute()</code> calls. Maps a route path to <code>true</code> (disable all meta) or an array of locale codes for which meta should be disabled.</td></tr><tr><td><code>missingWarn</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Show console warnings when a translation key is missing.</td></tr><tr><td><code>hmr</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Enable Hot Module Replacement for translation files in development. When <code>true</code>, changes to JSON translation files trigger an automatic reload without a full page refresh.</td></tr><tr><td><code>cacheMaxSize</code></td><td><code>number</code></td><td><code>0</code></td><td>Maximum number of entries in the in-memory translation cache. <code>0</code> means no limit.</td></tr><tr><td><code>cacheTtl</code></td><td><code>number</code></td><td><code>0</code></td><td>Time-to-live (in seconds) for cached translation entries. <code>0</code> means entries never expire.</td></tr><tr><td><code>numberFormats</code></td><td><code>Record&lt;string, Record&lt;string, Intl.NumberFormatOptions&gt;&gt;</code></td><td>—</td><td>Named number formats per locale (Vue I18n-compatible). Enables <code>$tn(1000, &#39;currency&#39;)</code> style calls.</td></tr><tr><td><code>datetimeFormats</code></td><td><code>Record&lt;string, Record&lt;string, Intl.DateTimeFormatOptions&gt;&gt;</code></td><td>—</td><td>Named datetime formats per locale (Vue I18n-compatible <code>datetimeFormats</code>). Enables <code>$td(date, &#39;short&#39;)</code> style calls.</td></tr><tr><td><code>httpCacheDuration</code></td><td><code>number</code></td><td><code>31536000</code></td><td>HTTP <code>Cache-Control</code> max-age (seconds) for <code>/{apiBaseUrl}/:page/:locale/data.json</code>. Applies in full only while <code>dateBuild</code> busts the URL (<code>?v=...</code>), which is the default: the response is then <code>public, max-age=…, immutable</code> and safe for browsers and CDNs. - <code>dateBuild: 0</code>/<code>&#39;&#39;</code> — the URL is stable, so this duration is <em>not</em> honoured; the response becomes <code>public, max-age=0, must-revalidate</code> instead. A long <code>max-age</code> on an unchanging URL pins the first payload a browser ever saw. - <code>0</code> — do not set <code>Cache-Control</code> at all (useful in local debugging) - Not applied in development (<code>import.meta.dev</code>) so HMR is not fought by the browser cache - Reaches only responses served through Nitro. Payloads copied into <code>public/</code> and served by the hosting platform take that platform&#39;s headers — see the Performance guide. Analogous to <code>@nuxtjs/i18n</code> experimental <code>httpCacheDuration</code> (v10.2.0), but as an explicit response header rather than Nitro <code>defineCachedEventHandler</code> maxAge.</td></tr><tr><td><code>dateBuild</code></td><td><code>string | number</code></td><td>—</td><td>Value used for cache-busting translation requests (<code>?v=...</code>). When not provided, the module falls back to <code>Date.now()</code> (non-deterministic). For reproducible/rolling deployments, set this to a stable value (e.g. a git SHA or build number).</td></tr><tr><td><code>experimental</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>—</td><td>Bucket for experimental/unstable options. Contents may change or be removed without notice between minor versions.</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to “See also”">​</a></h2><ul><li><a href="/nuxt-i18n-micro/guide/configuration">Configuration</a> — how these options work together</li><li><a href="/nuxt-i18n-micro/guide/performance">Performance</a> — what the payload options change at runtime</li><li><a href="/nuxt-i18n-micro/api/packages">Package APIs</a> — the exported API of every workspace package</li></ul>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};